                with st.expander(f"{a[1]} -- Lote: {nome_lote}"):
                    det = obter_animal(a[0])
                    c1,c2 = st.columns(2)
                    with c1:
                        st.write(f"ID: {a[0]} | Idade: {a[2]} meses")
