        if total >= lote[5]:
            st.error("Limite do lote atingido.")
        else:
            with st.form("form_animal"):
                a1,a2,a3 = st.columns(3)
                with a1: ident  = st.text_input("Brinco / Identificacao *", placeholder="BOI-001")
